EP=dict(id='cherami',title='The Pigeon Who Became A War Hero',
 lines=[{'t': 'A pigeon named Cher Ami became a hero of World War One.', 'v': 'narr', 'pad': 0.1, 'shots': [('cherami_hook', 1)]}, {'t': 'He was one of six hundred birds donated to the U.S. Army Pigeon Service in 1918.', 'v': 'narr', 'pad': 0.1, 'shots': [('cherami_s2', 1)]}, {'t': 'In October 1918, a group of soldiers known as the Lost Battalion was trapped in the Argonne Forest.', 'v': 'narr', 'pad': 0.1, 'shots': [('cherami_s3', 1)]}, {'t': 'According to popular legend, he carried a message that helped them, even after being shot in the breast, losing a leg, and being blinded in one eye.', 'v': 'narr', 'pad': 0.1, 'shots': [('cherami_s4', 1)]}, {'t': 'He flew about twenty-five miles back to his loft in just twenty-five minutes.', 'v': 'narr', 'pad': 0.1, 'shots': [('cherami_s5', 1)]}, {'t': 'Army medics saved his life, and he was shipped home to the United States.', 'v': 'narr', 'pad': 0.1, 'shots': [('cherami_s6', 1)]}, {'t': 'France gave him its Croix de Guerre medal for delivering twelve important messages at Verdun.', 'v': 'narr', 'pad': 0.1, 'shots': [('cherami_s7', 1)]}, {'t': 'But despite old news reports, he did not receive a Distinguished Service Cross.', 'v': 'narr2', 'pad': 0.6, 'shots': [('cherami_s8', 1)]}],
 sfx=[('cherami_hook', 0.04, 'whoosh'), ('cherami_hook', 0.4, 'pop'), ('cherami_s2', 0.4, 'pop'), ('cherami_s3', 0.4, 'pop'), ('cherami_s4', 0.4, 'pop'), ('cherami_s5', 0.4, 'pop'), ('cherami_s6', 0.4, 'pop'), ('cherami_s7', 0.4, 'pop'), ('cherami_s8', 0.4, 'pop'), ('cherami_s8', '%0.85', 'rimshot')])
